index accounts_device: CREATE INDEX accounts_device on accounts(device)
index accounts_type: CREATE INDEX accounts_type on accounts(type)
index directory_peer: CREATE INDEX directory_peer on directory(peer)
index group_members_member: CREATE INDEX group_members_member on group_members( member )
index media_account: CREATE INDEX media_account on media(account)
index objects_account: CREATE INDEX objects_account on objects(account)
index waiting_account: CREATE INDEX waiting_account on waiting(account, created)
table accounts: CREATE TABLE accounts (id text not null primary key, type text not null, label text not null default '', identifier text not null default '', data text not null default '', created integer not null, verified integer not null default 0, enabled integer not null default 1, "default" text not null default '', last_delivered integer not null default 0, device text not null default '')
table alerts: CREATE TABLE alerts (id integer primary key autoincrement, account text not null, row text not null, event text not null default '', answer text not null, created integer not null, unique (account, row, event))
table apps: CREATE TABLE apps (app text primary key, setup integer not null default 0)
table blobs: CREATE TABLE blobs (account text not null, cid text not null, type text not null default '', size integer not null default 0, created integer not null, primary key (account, cid))
table blocked: CREATE TABLE blocked (actor text not null primary key, created integer not null)
table blocks: CREATE TABLE blocks (domain text not null primary key, created integer not null)
table classes: CREATE TABLE classes (class text not null primary key, app text not null)
table devices: CREATE TABLE devices (id text not null primary key, label text not null default '', created integer not null, seen integer not null default 0)
table directory: CREATE TABLE directory (entity text not null, peer text not null, fingerprint text not null default '', created integer not null, seen integer not null, confirmed integer not null default 0, primary key (entity, peer))
table filters: CREATE TABLE filters (id integer primary key autoincrement, account text not null, title text not null, context text not null, action text not null default 'warn', keywords text not null default '[]', expires integer not null default 0, created integer not null)
table followers: CREATE TABLE followers (account text not null, actor text not null, inbox text not null, shared text not null default '', created integer not null, primary key (account, actor))
table following: CREATE TABLE following (account text not null, actor text not null, inbox text not null default '', activity text not null, accepted integer not null default 0, created integer not null, primary key (account, actor))
table group_members: CREATE TABLE group_members ( parent text not null, member text not null, type text not null, created integer not null, primary key( parent, member ) )
table groups: CREATE TABLE groups ( id text not null primary key, name text not null, description text not null default '', created integer not null)
table interests: CREATE TABLE interests (qid text not null primary key, weight integer not null default 100, updated integer not null default 0)
table keys: CREATE TABLE keys (account text not null, kind text not null, algorithm text not null, public text not null, private text not null default '', created integer not null, primary key (account, kind))
table markers: CREATE TABLE markers (account text not null, timeline text not null, position text not null, version integer not null default 0, updated integer not null, primary key (account, timeline))
table media: CREATE TABLE media (id text not null primary key, account text not null, type text not null default '', name text not null default '', description text not null default '', size integer not null default 0, created integer not null)
table muted: CREATE TABLE muted (actor text not null primary key, created integer not null)
table nodes: CREATE TABLE nodes (account text not null, cid text not null, data blob not null, primary key (account, cid))
table numbers: CREATE TABLE numbers (number integer primary key autoincrement, kind text not null, id text not null, created integer not null, unique (kind, id))
table objects: CREATE TABLE objects (id text not null primary key, account text not null, app text not null default '', type text not null default '', addressing text not null default '', created integer not null, updated integer not null default 0, deleted integer not null default 0)
table paths: CREATE TABLE paths (path text not null primary key, app text not null)
table permissions: CREATE TABLE permissions ( app text not null, permission text not null, object text not null default '', granted integer not null default 0, created integer not null default 0, primary key ( app, permission, object ) )
table preferences: CREATE TABLE preferences (name text primary key, value text not null)
table records: CREATE TABLE records (account text not null, collection text not null, rkey text not null, cid text not null, created integer not null, updated integer not null default 0, primary key (account, collection, rkey))
table repositories: CREATE TABLE repositories (account text not null primary key, did text not null, root text not null default '', head text not null default '', rev text not null default '', created integer not null, updated integer not null default 0)
table requests: CREATE TABLE requests (account text not null, key text not null, result text not null, created integer not null, primary key (account, key))
table services: CREATE TABLE services (service text not null primary key, app text not null)
table settings: CREATE TABLE settings (key text not null primary key, text text not null default '', number integer not null default 0)
table snapshots: CREATE TABLE snapshots (kind text not null, key text not null, document text not null, created integer not null, updated integer not null, primary key (kind, key))
table snowflakes: CREATE TABLE snowflakes (number integer primary key, kind text not null, key text not null, unique (kind, key))
table subscriptions: CREATE TABLE subscriptions (token text not null primary key, account text not null, endpoint text not null, auth text not null, key text not null, alerts text not null default '{}', policy text not null default 'all', standard integer not null default 0, created integer not null)
table versions: CREATE TABLE versions (app text not null primary key, version text not null default '', track text not null default '')
table waiting: CREATE TABLE waiting (id text not null primary key, account text not null, path text not null, cid text not null default '', sourced integer not null default 0, created integer not null)
